// --- source: fingerprint.ts ---
/** Replay-safe fingerprint primitives (shared by causal/timeline modules). */

export function o6kAgent24Fnv1a32(input: string, seed = 0x811c9dc5): number {
  let hash = seed >>> 0;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash >>> 0;
}

export function o6kAgent24StableStringify(value: unknown): string {
  if (value === null || value === undefined) return String(value);
  if (typeof value === 'number' || typeof value === 'boolean') return JSON.stringify(value);
  if (typeof value === 'string') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(o6kAgent24StableStringify).join(',') + ']';
  if (typeof value === 'object') {
    const obj = value as Record<string, unknown>;
    const keys = Object.keys(obj)
      .filter(k => k !== 'createdAtTimestamp' && k !== 'timestamp' && !k.endsWith('AtMs'))
      .sort();
    return '{' + keys.map(k => JSON.stringify(k) + ':' + o6kAgent24StableStringify(obj[k])).join(',') + '}';
  }
  return JSON.stringify(String(value));
}

export function o6kAgent24Fingerprint(label: string, payload: unknown): string {
  const body = o6kAgent24StableStringify(payload);
  const h = o6kAgent24Fnv1a32(label + '|' + body);
  return `o6k24_${label}_${h.toString(16).padStart(8, '0')}`;
}


// --- source: causal-records.ts ---

/** Minimal ledger event shape for replay-safe causal indexing (matches V9.4 ledger fields). */
export interface Agent24LedgerEventLike {
  id?: string;
  eventId?: string;
  turn?: number;
  day?: number;
  title?: string;
  description?: string;
  message?: string;
  eventType?: string;
  parentEventId?: string;
  rootEventId?: string;
  causalChainId?: string;
  causalDepth?: number;
  causalLinkage?: {
    causalChainId?: string;
    parentEventId?: string;
    rootEventId?: string;
    causalDepth?: number;
  };
}

export interface Agent24CausalRecord {
  recordId: string;
  eventId: string;
  turn: number;
  day: number;
  sequence: number;
  causalChainId: string;
  parentEventId: string | null;
  rootEventId: string | null;
  causalDepth: number;
  summary: string;
  fingerprint: string;
}

export interface Agent24CausalRecordIndex {
  indexId: string;
  recordCount: number;
  chainCount: number;
  maxDepth: number;
  recordsByEventId: Record<string, Agent24CausalRecord>;
  chainsById: Record<string, string[]>;
  deterministicFingerprint: string;
}

function linkageOf(evt: Agent24LedgerEventLike) {
  return {
    causalChainId:
      evt.causalLinkage?.causalChainId || evt.causalChainId || evt.causalLinkage?.rootEventId || evt.rootEventId || 'chain_root',
    parentEventId: evt.causalLinkage?.parentEventId || evt.parentEventId || null,
    rootEventId: evt.causalLinkage?.rootEventId || evt.rootEventId || null,
    causalDepth:
      typeof evt.causalLinkage?.causalDepth === 'number'
        ? evt.causalLinkage.causalDepth
        : typeof evt.causalDepth === 'number'
          ? evt.causalDepth
          : 0,
  };
}

export function buildAgent24CausalRecordIndex(events: Agent24LedgerEventLike[]): Agent24CausalRecordIndex {
  const recordsByEventId: Record<string, Agent24CausalRecord> = {};
  const chainsById: Record<string, string[]> = {};
  let maxDepth = 0;
  let seq = 0;

  for (const evt of events) {
    seq++;
    const eventId = String(evt.id || evt.eventId || `evt_${seq}`);
    const link = linkageOf(evt);
    const turn = Number(evt.turn ?? evt.day ?? 1);
    const day = Number(evt.day ?? evt.turn ?? 1);
    const summary = String(evt.title || evt.description || evt.message || evt.eventType || '').slice(0, 160);
    const record: Agent24CausalRecord = {
      recordId: o6kAgent24Fingerprint('causal_record', { eventId, seq, turn, link }),
      eventId,
      turn,
      day,
      sequence: seq,
      causalChainId: link.causalChainId,
      parentEventId: link.parentEventId,
      rootEventId: link.rootEventId,
      causalDepth: link.causalDepth,
      summary,
      fingerprint: o6kAgent24Fingerprint('causal_evt', { eventId, turn, summary, link }),
    };
    recordsByEventId[eventId] = record;
    if (!chainsById[link.causalChainId]) chainsById[link.causalChainId] = [];
    chainsById[link.causalChainId].push(eventId);
    if (link.causalDepth > maxDepth) maxDepth = link.causalDepth;
  }

  for (const chainId of Object.keys(chainsById)) {
    chainsById[chainId].sort((a, b) => {
      const ra = recordsByEventId[a];
      const rb = recordsByEventId[b];
      return (ra?.sequence ?? 0) - (rb?.sequence ?? 0) || a.localeCompare(b);
    });
  }

  const chainKeys = Object.keys(chainsById).sort();
  const payload = {
    chainKeys,
    recordFingerprints: Object.keys(recordsByEventId)
      .sort()
      .map(id => recordsByEventId[id].fingerprint),
  };

  return {
    indexId: o6kAgent24Fingerprint('causal_index', payload),
    recordCount: Object.keys(recordsByEventId).length,
    chainCount: chainKeys.length,
    maxDepth,
    recordsByEventId,
    chainsById,
    deterministicFingerprint: o6kAgent24Fingerprint('causal_index_body', o6kAgent24StableStringify(payload)),
  };
}

export function pickCausalChain(index: Agent24CausalRecordIndex, chainId: string): Agent24CausalRecord[] {
  const ids = index.chainsById[chainId] || [];
  return ids.map(id => index.recordsByEventId[id]).filter(Boolean);
}


// --- source: timeline-registry.ts ---

export type Agent24TimelineStatus = 'main' | 'branch' | 'simulated' | 'archived';

export interface Agent24TimelineBranchNodeLike {
  nodeId: string;
  parentNodeId?: string | null;
  branchTurn?: number;
  branchDay?: number;
  label?: string;
  triggerReason?: string;
  childNodeIds?: string[];
}

export interface Agent24TimelineRegistryInput {
  matchId: string;
  activeTimelineId?: string;
  activeNodeId?: string;
  nodesById?: Record<string, Agent24TimelineBranchNodeLike>;
  whatIfTimelines?: Array<{
    timelineId: string;
    title?: string;
    parentTimelineId?: string | null;
    status?: Agent24TimelineStatus;
    branchedAtNodeId?: string;
  }>;
}

export interface Agent24TimelineEntry {
  timelineId: string;
  status: Agent24TimelineStatus;
  parentTimelineId: string | null;
  branchedAtNodeId: string | null;
  branchTurn: number | null;
  label: string;
  fingerprint: string;
}

export interface Agent24TimelineRegistry {
  registryId: string;
  matchId: string;
  activeTimelineId: string;
  activeNodeId: string;
  entries: Agent24TimelineEntry[];
  branchNodeOrder: string[];
  deterministicFingerprint: string;
}

export function buildAgent24TimelineRegistry(input: Agent24TimelineRegistryInput): Agent24TimelineRegistry {
  const nodes = input.nodesById || {};
  const branchNodeOrder = Object.keys(nodes).sort((a, b) => {
    const ta = nodes[a]?.branchTurn ?? 0;
    const tb = nodes[b]?.branchTurn ?? 0;
    return ta - tb || a.localeCompare(b);
  });

  const entries: Agent24TimelineEntry[] = [];
  const mainId = input.activeTimelineId || 'main';
  entries.push({
    timelineId: mainId,
    status: 'main',
    parentTimelineId: null,
    branchedAtNodeId: input.activeNodeId || 'root',
    branchTurn: null,
    label: 'Main timeline',
    fingerprint: o6kAgent24Fingerprint('timeline_main', { matchId: input.matchId, mainId }),
  });

  for (const nodeId of branchNodeOrder) {
    const node = nodes[nodeId];
    if (!node) continue;
    entries.push({
      timelineId: `branch:${nodeId}`,
      status: 'branch',
      parentTimelineId: mainId,
      branchedAtNodeId: nodeId,
      branchTurn: node.branchTurn ?? null,
      label: node.label || nodeId,
      fingerprint: o6kAgent24Fingerprint('timeline_branch', {
        nodeId,
        parent: node.parentNodeId,
        turn: node.branchTurn,
        reason: node.triggerReason,
      }),
    });
  }

  for (const wt of input.whatIfTimelines || []) {
    entries.push({
      timelineId: wt.timelineId,
      status: (wt.status as Agent24TimelineStatus) || 'simulated',
      parentTimelineId: wt.parentTimelineId ?? mainId,
      branchedAtNodeId: wt.branchedAtNodeId ?? null,
      branchTurn: null,
      label: wt.title || wt.timelineId,
      fingerprint: o6kAgent24Fingerprint('timeline_whatif', wt),
    });
  }

  entries.sort((a, b) => a.timelineId.localeCompare(b.timelineId));
  const payload = entries.map(e => ({ id: e.timelineId, fp: e.fingerprint }));

  return {
    registryId: o6kAgent24Fingerprint('timeline_registry', { matchId: input.matchId, payload }),
    matchId: input.matchId,
    activeTimelineId: mainId,
    activeNodeId: input.activeNodeId || 'root',
    entries,
    branchNodeOrder,
    deterministicFingerprint: o6kAgent24Fingerprint('timeline_registry_body', payload),
  };
}


// --- source: late-game-replay.ts ---

export type Agent24MatchPhase = 'opening' | 'midgame' | 'endgame' | 'overtime';

export interface Agent24LateGameReplayContext {
  turn: number;
  day: number;
  maxTurns?: number;
  endgameStartTurn?: number;
  overtimeStartTurn?: number;
  victoryDeclared?: boolean;
  checkpointKinds?: string[];
}

export interface Agent24LateGameReplayAssessment {
  phase: Agent24MatchPhase;
  isLateGame: boolean;
  requiresEndgameCheckpoint: boolean;
  recommendedCheckpointKinds: string[];
  fingerprint: string;
}

const DEFAULT_ENDGAME_RATIO = 0.75;
const DEFAULT_OVERTIME_RATIO = 0.92;

export function classifyAgent24MatchPhase(ctx: Agent24LateGameReplayContext): Agent24MatchPhase {
  const maxTurns = ctx.maxTurns && ctx.maxTurns > 0 ? ctx.maxTurns : 120;
  const endTurn = ctx.endgameStartTurn ?? Math.floor(maxTurns * DEFAULT_ENDGAME_RATIO);
  const otTurn = ctx.overtimeStartTurn ?? Math.floor(maxTurns * DEFAULT_OVERTIME_RATIO);
  if (ctx.victoryDeclared) return 'overtime';
  if (ctx.turn >= otTurn || ctx.day >= otTurn) return 'overtime';
  if (ctx.turn >= endTurn || ctx.day >= endTurn) return 'endgame';
  if (ctx.turn >= Math.floor(maxTurns * 0.35)) return 'midgame';
  return 'opening';
}

export function assessAgent24LateGameReplay(ctx: Agent24LateGameReplayContext): Agent24LateGameReplayAssessment {
  const phase = classifyAgent24MatchPhase(ctx);
  const isLateGame = phase === 'endgame' || phase === 'overtime';
  const recommendedCheckpointKinds = isLateGame
    ? ['endgame_start', 'lead_change', 'major_action', 'turn', 'match_end']
    : ['turn', 'day'];
  const requiresEndgameCheckpoint =
    isLateGame && !(ctx.checkpointKinds || []).some(k => k === 'endgame_start' || k === 'match_end');

  const payload = { phase, isLateGame, requiresEndgameCheckpoint, recommendedCheckpointKinds, turn: ctx.turn };
  return {
    phase,
    isLateGame,
    requiresEndgameCheckpoint,
    recommendedCheckpointKinds,
    fingerprint: o6kAgent24Fingerprint('late_game_replay', payload),
  };
}


// --- source: analytics-depth.ts ---

export interface Agent24ReplayDeterminismBundleSlice {
  snapshot: O6kHistoricalAnalyticsSnapshot;
  causalIndex: Agent24CausalRecordIndex;
  timelineRegistry: Agent24TimelineRegistry;
  lateGame: Agent24LateGameReplayAssessment;
  twinBuildPassed: boolean;
}

export interface Agent24MilestoneCategoryRollup {
  category: string;
  hitCount: number;
  weightSum: number;
}

export interface Agent24CausalDepthHistogram {
  depth: number;
  count: number;
}

export interface Agent24ReplayAnalyticsDepth {
  depthId: string;
  milestoneCategoryRollups: Agent24MilestoneCategoryRollup[];
  totalMilestoneWeight: number;
  causalDepthHistogram: Agent24CausalDepthHistogram[];
  longestCausalChainLength: number;
  timelineEntryCount: number;
  branchTimelineCount: number;
  replayEventCount: number;
  checkpointCount: number;
  lateGamePhase: string;
  integrityScore: number;
  deterministicFingerprint: string;
}

export interface Agent24ReplayBundleDiff {
  milestoneHitDelta: number;
  causalRecordDelta: number;
  timelineEntryDelta: number;
  integrityChanged: boolean;
  compositeChanged: boolean;
  summary: string;
}

function buildCategoryRollups(snapshot: O6kHistoricalAnalyticsSnapshot): Agent24MilestoneCategoryRollup[] {
  const map = new Map<string, { hitCount: number; weightSum: number }>();
  for (const hit of snapshot.milestoneHits) {
    const cur = map.get(hit.category) || { hitCount: 0, weightSum: 0 };
    cur.hitCount += 1;
    cur.weightSum += hit.weight;
    map.set(hit.category, cur);
  }
  return [...map.entries()]
    .map(([category, v]) => ({ category, hitCount: v.hitCount, weightSum: v.weightSum }))
    .sort((a, b) => a.category.localeCompare(b.category));
}

function buildCausalDepthHistogram(index: Agent24CausalRecordIndex): Agent24CausalDepthHistogram[] {
  const counts = new Map<number, number>();
  for (const rec of Object.values(index.recordsByEventId)) {
    const d = rec.causalDepth;
    counts.set(d, (counts.get(d) || 0) + 1);
  }
  return [...counts.entries()]
    .map(([depth, count]) => ({ depth, count }))
    .sort((a, b) => a.depth - b.depth);
}

function longestChainLength(index: Agent24CausalRecordIndex): number {
  let max = 0;
  for (const ids of Object.values(index.chainsById)) {
    if (ids.length > max) max = ids.length;
  }
  return max;
}

function computeIntegrityScore(input: {
  snapshot: O6kHistoricalAnalyticsSnapshot;
  causalIndex: Agent24CausalRecordIndex;
  timelineRegistry: Agent24TimelineRegistry;
  lateGame: Agent24LateGameReplayAssessment;
  twinBuildPassed: boolean;
}): number {
  let score = 0;
  if (input.snapshot.integrity.deterministicMode) score += 25;
  if (input.twinBuildPassed) score += 25;
  if (input.causalIndex.recordCount > 0) score += 15;
  if (input.timelineRegistry.entries.length >= 1) score += 10;
  if (!input.lateGame.requiresEndgameCheckpoint || !input.lateGame.isLateGame) score += 15;
  else score += 5;
  if (input.snapshot.integrity.replayEventCount >= 0) score += 10;
  return Math.min(100, score);
}

export function buildAgent24ReplayAnalyticsDepth(
  bundle: Agent24ReplayDeterminismBundleSlice,
): Agent24ReplayAnalyticsDepth {
  const rollups = buildCategoryRollups(bundle.snapshot);
  const histogram = buildCausalDepthHistogram(bundle.causalIndex);
  const branchCount = bundle.timelineRegistry.entries.filter(e => e.status === 'branch').length;
  const totalWeight = rollups.reduce((s, r) => s + r.weightSum, 0);
  const integrityScore = computeIntegrityScore({
    snapshot: bundle.snapshot,
    causalIndex: bundle.causalIndex,
    timelineRegistry: bundle.timelineRegistry,
    lateGame: bundle.lateGame,
    twinBuildPassed: bundle.twinBuildPassed,
  });
  const payload = {
    rollups,
    histogram,
    branchCount,
    totalWeight,
    integrityScore,
    replayEventCount: bundle.snapshot.integrity.replayEventCount,
    checkpointCount: bundle.snapshot.integrity.checkpointCount,
    phase: bundle.lateGame.phase,
  };
  return {
    depthId: o6kAgent24Fingerprint('analytics_depth', payload),
    milestoneCategoryRollups: rollups,
    totalMilestoneWeight: totalWeight,
    causalDepthHistogram: histogram,
    longestCausalChainLength: longestChainLength(bundle.causalIndex),
    timelineEntryCount: bundle.timelineRegistry.entries.length,
    branchTimelineCount: branchCount,
    replayEventCount: bundle.snapshot.integrity.replayEventCount,
    checkpointCount: bundle.snapshot.integrity.checkpointCount,
    lateGamePhase: bundle.lateGame.phase,
    integrityScore,
    deterministicFingerprint: o6kAgent24Fingerprint('analytics_depth_body', payload),
  };
}

export function diffAgent24ReplayBundles(
  before: Agent24ReplayDeterminismBundleSlice & { compositeFingerprint: string },
  after: Agent24ReplayDeterminismBundleSlice & { compositeFingerprint: string },
): Agent24ReplayBundleDiff {
  const milestoneHitDelta = after.snapshot.milestoneHits.length - before.snapshot.milestoneHits.length;
  const causalRecordDelta = after.causalIndex.recordCount - before.causalIndex.recordCount;
  const timelineEntryDelta = after.timelineRegistry.entries.length - before.timelineRegistry.entries.length;
  const integrityChanged = before.snapshot.integrity.fingerprint !== after.snapshot.integrity.fingerprint;
  const compositeChanged = before.compositeFingerprint !== after.compositeFingerprint;
  return {
    milestoneHitDelta,
    causalRecordDelta,
    timelineEntryDelta,
    integrityChanged,
    compositeChanged,
    summary: `Milestones ${milestoneHitDelta >= 0 ? '+' : ''}${milestoneHitDelta}; causal ${causalRecordDelta >= 0 ? '+' : ''}${causalRecordDelta}; timelines ${timelineEntryDelta >= 0 ? '+' : ''}${timelineEntryDelta}; integrity ${integrityChanged ? 'changed' : 'stable'}.`,
  };
}

export function runAgent24AnalyticsDepthSelfTests(): Array<{ name: string; passed: boolean; detail: string }> {
  const results: Array<{ name: string; passed: boolean; detail: string }> = [];
  const emptySnap = {
    snapshotId: 's',
    matchId: 'm',
    activeTimelineId: 'main',
    generatedAtTurn: 1,
    generatedAtDay: 1,
    milestoneHits: [],
    timelineSlices: [],
    replayBranchNodeIds: [],
    integrity: { deterministicMode: true, replayEventCount: 0, checkpointCount: 0, fingerprint: 'fp' },
  } as O6kHistoricalAnalyticsSnapshot;
  const depth = buildAgent24ReplayAnalyticsDepth({
    snapshot: emptySnap,
    causalIndex: {
      indexId: 'i',
      recordCount: 0,
      chainCount: 0,
      maxDepth: 0,
      recordsByEventId: {},
      chainsById: {},
      deterministicFingerprint: 'c',
    },
    timelineRegistry: {
      registryId: 'r',
      matchId: 'm',
      activeTimelineId: 'main',
      activeNodeId: 'root',
      entries: [],
      branchNodeOrder: [],
      deterministicFingerprint: 't',
    },
    lateGame: {
      phase: 'opening',
      isLateGame: false,
      requiresEndgameCheckpoint: false,
      recommendedCheckpointKinds: ['turn'],
      fingerprint: 'l',
    },
    twinBuildPassed: true,
  });
  results.push({
    name: 'depth_empty_integrity_score',
    passed: depth.integrityScore === 75,
    detail: `score=${depth.integrityScore}`,
  });
  results.push({
    name: 'depth_fingerprint_stable',
    passed: depth.deterministicFingerprint === buildAgent24ReplayAnalyticsDepth({
      snapshot: emptySnap,
      causalIndex: {
        indexId: 'i',
        recordCount: 0,
        chainCount: 0,
        maxDepth: 0,
        recordsByEventId: {},
        chainsById: {},
        deterministicFingerprint: 'c',
      },
      timelineRegistry: {
        registryId: 'r',
        matchId: 'm',
        activeTimelineId: 'main',
        activeNodeId: 'root',
        entries: [],
        branchNodeOrder: [],
        deterministicFingerprint: 't',
      },
      lateGame: {
        phase: 'opening',
        isLateGame: false,
        requiresEndgameCheckpoint: false,
        recommendedCheckpointKinds: ['turn'],
        fingerprint: 'l',
      },
      twinBuildPassed: true,
    }).deterministicFingerprint,
    detail: 'twin depth fingerprint',
  });
  return results;
}


// --- source: replay-scenarios.ts ---

export type Agent24ReplayScenarioId =
  | 'baseline_match'
  | 'branch_heavy'
  | 'late_game_overtime'
  | 'causal_chain_stress'
  | 'multi_session_resume';

export interface Agent24ReplayScenarioDefinition {
  id: Agent24ReplayScenarioId;
  title: string;
  description: string;
  /** Minimum replay events expected when scenario is satisfied. */
  minReplayEvents: number;
  /** Minimum branch nodes when applicable. */
  minBranchNodes: number;
  requiresLateGame: boolean;
  requiresCausalDepth: number;
}

export interface Agent24ReplayScenarioInput {
  replayEventCount: number;
  branchNodeCount: number;
  isLateGame: boolean;
  maxCausalDepth: number;
  sessionCount: number;
}

export interface Agent24ReplayScenarioAssessment {
  scenarioId: Agent24ReplayScenarioId;
  satisfied: boolean;
  score: number;
  detail: string;
  fingerprint: string;
}

export interface Agent24ReplayScenarioSuiteResult {
  suiteId: string;
  assessments: Agent24ReplayScenarioAssessment[];
  satisfiedCount: number;
  deterministicFingerprint: string;
}

export const AGENT24_REPLAY_SCENARIO_CATALOG: Agent24ReplayScenarioDefinition[] = [
  {
    id: 'baseline_match',
    title: 'Baseline match replay',
    description: 'Standard single-timeline match with checkpoints.',
    minReplayEvents: 1,
    minBranchNodes: 0,
    requiresLateGame: false,
    requiresCausalDepth: 0,
  },
  {
    id: 'branch_heavy',
    title: 'Branch-heavy what-if',
    description: 'Multiple replay branches recorded.',
    minReplayEvents: 2,
    minBranchNodes: 2,
    requiresLateGame: false,
    requiresCausalDepth: 0,
  },
  {
    id: 'late_game_overtime',
    title: 'Late game / overtime',
    description: 'Endgame phase with checkpoint coverage.',
    minReplayEvents: 1,
    minBranchNodes: 0,
    requiresLateGame: true,
    requiresCausalDepth: 0,
  },
  {
    id: 'causal_chain_stress',
    title: 'Deep causal chains',
    description: 'Ledger causal depth stress for audit replay.',
    minReplayEvents: 0,
    minBranchNodes: 0,
    requiresLateGame: false,
    requiresCausalDepth: 2,
  },
  {
    id: 'multi_session_resume',
    title: 'Multi-session resume',
    description: 'Match spans more than one persisted session.',
    minReplayEvents: 1,
    minBranchNodes: 0,
    requiresLateGame: false,
    requiresCausalDepth: 0,
  },
];

function assessOne(def: Agent24ReplayScenarioDefinition, input: Agent24ReplayScenarioInput): Agent24ReplayScenarioAssessment {
  let satisfied = true;
  const checks: string[] = [];

  if (input.replayEventCount < def.minReplayEvents) {
    satisfied = false;
    checks.push(`replayEvents ${input.replayEventCount}<${def.minReplayEvents}`);
  }
  if (input.branchNodeCount < def.minBranchNodes) {
    satisfied = false;
    checks.push(`branches ${input.branchNodeCount}<${def.minBranchNodes}`);
  }
  if (def.requiresLateGame && !input.isLateGame) {
    satisfied = false;
    checks.push('lateGame required');
  }
  if (input.maxCausalDepth < def.requiresCausalDepth) {
    satisfied = false;
    checks.push(`causalDepth ${input.maxCausalDepth}<${def.requiresCausalDepth}`);
  }
  if (def.id === 'multi_session_resume' && input.sessionCount < 2) {
    satisfied = false;
    checks.push(`sessions ${input.sessionCount}<2`);
  }

  const score = satisfied ? 100 : Math.max(0, 100 - checks.length * 25);
  const payload = { id: def.id, satisfied, score, checks };
  return {
    scenarioId: def.id,
    satisfied,
    score,
    detail: satisfied ? 'Scenario satisfied.' : checks.join('; '),
    fingerprint: o6kAgent24Fingerprint('replay_scenario', payload),
  };
}

export function runAgent24ReplayScenarioSuite(input: Agent24ReplayScenarioInput): Agent24ReplayScenarioSuiteResult {
  const assessments = AGENT24_REPLAY_SCENARIO_CATALOG.map(def => assessOne(def, input)).sort((a, b) =>
    a.scenarioId.localeCompare(b.scenarioId),
  );
  const satisfiedCount = assessments.filter(a => a.satisfied).length;
  const payload = assessments.map(a => ({ id: a.scenarioId, fp: a.fingerprint, ok: a.satisfied }));
  return {
    suiteId: o6kAgent24Fingerprint('scenario_suite', { satisfiedCount, payload }),
    assessments,
    satisfiedCount,
    deterministicFingerprint: o6kAgent24Fingerprint('scenario_suite_body', payload),
  };
}


// --- source: audit-trails.ts ---

export type Agent24AuditTrailAction =
  | 'replay_checkpoint'
  | 'branch_created'
  | 'branch_switched'
  | 'timeline_merged'
  | 'session_saved'
  | 'session_resumed'
  | 'determinism_verified'
  | 'scenario_evaluated';

export interface Agent24AuditTrailEntry {
  entryId: string;
  sequence: number;
  turn: number;
  day: number;
  action: Agent24AuditTrailAction;
  actorId: string;
  summary: string;
  relatedTimelineId: string | null;
  relatedSessionId: string | null;
  fingerprint: string;
}

export interface Agent24AuditTrailBuildInput {
  matchId: string;
  turn: number;
  day: number;
  entries: Array<{
    action: Agent24AuditTrailAction;
    actorId?: string;
    summary: string;
    relatedTimelineId?: string | null;
    relatedSessionId?: string | null;
    turn?: number;
    day?: number;
  }>;
}

export interface Agent24AuditTrail {
  trailId: string;
  matchId: string;
  entryCount: number;
  entries: Agent24AuditTrailEntry[];
  actionCounts: Record<Agent24AuditTrailAction, number>;
  deterministicFingerprint: string;
}

const ZERO_COUNTS = (): Record<Agent24AuditTrailAction, number> => ({
  replay_checkpoint: 0,
  branch_created: 0,
  branch_switched: 0,
  timeline_merged: 0,
  session_saved: 0,
  session_resumed: 0,
  determinism_verified: 0,
  scenario_evaluated: 0,
});

export function buildAgent24AuditTrail(input: Agent24AuditTrailBuildInput): Agent24AuditTrail {
  const entries: Agent24AuditTrailEntry[] = [];
  const actionCounts = ZERO_COUNTS();
  let seq = 0;

  const sortedRaw = [...input.entries].sort(
    (a, b) => (a.turn ?? input.turn) - (b.turn ?? input.turn) || a.summary.localeCompare(b.summary),
  );

  for (const raw of sortedRaw) {
    seq++;
    const turn = raw.turn ?? input.turn;
    const day = raw.day ?? input.day;
    const action = raw.action;
    actionCounts[action] += 1;
    const body = {
      seq,
      action,
      summary: raw.summary.slice(0, 200),
      timeline: raw.relatedTimelineId ?? null,
      session: raw.relatedSessionId ?? null,
    };
    entries.push({
      entryId: o6kAgent24Fingerprint('audit_entry', { matchId: input.matchId, ...body }),
      sequence: seq,
      turn,
      day,
      action,
      actorId: raw.actorId || 'system',
      summary: raw.summary.slice(0, 200),
      relatedTimelineId: raw.relatedTimelineId ?? null,
      relatedSessionId: raw.relatedSessionId ?? null,
      fingerprint: o6kAgent24Fingerprint('audit_evt', body),
    });
  }

  const fpPayload = {
    entries: entries.map(e => e.fingerprint),
    actionCounts,
  };

  return {
    trailId: o6kAgent24Fingerprint('audit_trail', { matchId: input.matchId, count: entries.length }),
    matchId: input.matchId,
    entryCount: entries.length,
    entries,
    actionCounts,
    deterministicFingerprint: o6kAgent24Fingerprint('audit_trail_body', o6kAgent24StableStringify(fpPayload)),
  };
}

export function mergeAgent24AuditTrails(a: Agent24AuditTrail, b: Agent24AuditTrail): Agent24AuditTrail {
  if (a.matchId !== b.matchId) {
    throw new Error('Cannot merge audit trails for different matches');
  }
  const combined = [...a.entries, ...b.entries].sort((x, y) => x.sequence - y.sequence || x.entryId.localeCompare(y.entryId));
  return buildAgent24AuditTrail({
    matchId: a.matchId,
    turn: Math.max(a.entries.at(-1)?.turn ?? 0, b.entries.at(-1)?.turn ?? 0),
    day: Math.max(a.entries.at(-1)?.day ?? 0, b.entries.at(-1)?.day ?? 0),
    entries: combined.map(e => ({
      action: e.action,
      actorId: e.actorId,
      summary: e.summary,
      relatedTimelineId: e.relatedTimelineId,
      relatedSessionId: e.relatedSessionId,
      turn: e.turn,
      day: e.day,
    })),
  });
}


// --- source: multi-session.ts ---

export interface Agent24ReplaySessionRecord {
  sessionId: string;
  matchId: string;
  sessionIndex: number;
  startedAtTurn: number;
  endedAtTurn: number;
  replayEventCount: number;
  branchNodeCount: number;
  continuityToken: string;
  fingerprint: string;
}

export interface Agent24MultiSessionInput {
  matchId: string;
  sessions: Array<{
    sessionId: string;
    startedAtTurn: number;
    endedAtTurn: number;
    replayEventCount: number;
    branchNodeCount: number;
  }>;
}

export interface Agent24MultiSessionContinuity {
  continuityId: string;
  matchId: string;
  sessionCount: number;
  totalReplayEvents: number;
  totalBranchNodes: number;
  spanTurns: number;
  sessions: Agent24ReplaySessionRecord[];
  resumeSafe: boolean;
  deterministicFingerprint: string;
}

export function buildAgent24MultiSessionContinuity(input: Agent24MultiSessionInput): Agent24MultiSessionContinuity {
  const sorted = [...input.sessions].sort((a, b) => a.startedAtTurn - b.startedAtTurn || a.sessionId.localeCompare(b.sessionId));
  const sessions: Agent24ReplaySessionRecord[] = sorted.map((s, idx) => {
    const prev = sorted[idx - 1];
    const continuityToken = o6kAgent24Fingerprint('session_link', {
      matchId: input.matchId,
      prev: prev?.sessionId ?? 'none',
      cur: s.sessionId,
      turn: s.startedAtTurn,
    });
    return {
      sessionId: s.sessionId,
      matchId: input.matchId,
      sessionIndex: idx,
      startedAtTurn: s.startedAtTurn,
      endedAtTurn: s.endedAtTurn,
      replayEventCount: s.replayEventCount,
      branchNodeCount: s.branchNodeCount,
      continuityToken,
      fingerprint: o6kAgent24Fingerprint('session_record', { ...s, idx }),
    };
  });

  let resumeSafe = sessions.length > 0;
  for (let i = 1; i < sessions.length; i++) {
    if (sessions[i].startedAtTurn < sessions[i - 1].endedAtTurn) {
      resumeSafe = false;
      break;
    }
  }

  const totalReplayEvents = sessions.reduce((s, r) => s + r.replayEventCount, 0);
  const totalBranchNodes = sessions.reduce((s, r) => s + r.branchNodeCount, 0);
  const minTurn = sessions[0]?.startedAtTurn ?? 0;
  const maxTurn = sessions.at(-1)?.endedAtTurn ?? 0;
  const payload = {
    sessionIds: sessions.map(s => s.sessionId),
    fingerprints: sessions.map(s => s.fingerprint),
    resumeSafe,
    totalReplayEvents,
  };

  return {
    continuityId: o6kAgent24Fingerprint('multi_session', { matchId: input.matchId, count: sessions.length }),
    matchId: input.matchId,
    sessionCount: sessions.length,
    totalReplayEvents,
    totalBranchNodes,
    spanTurns: Math.max(0, maxTurn - minTurn),
    sessions,
    resumeSafe,
    deterministicFingerprint: o6kAgent24Fingerprint('multi_session_body', payload),
  };
}


// --- source: timeline-divergence.ts ---

export interface Agent24BranchDivergenceMetric {
  timelineAId: string;
  timelineBId: string;
  divergenceTurnEstimate: number;
  branchLabelDelta: string;
  fingerprint: string;
}

export interface Agent24TimelineDivergenceReport {
  reportId: string;
  matchId: string;
  pairCount: number;
  metrics: Agent24BranchDivergenceMetric[];
  maxDivergenceTurn: number;
  deterministicFingerprint: string;
}

export interface Agent24TimelineDivergenceInput {
  matchId: string;
  registry: Agent24TimelineRegistry;
  branchTurnHints?: Record<string, number>;
}

export function buildAgent24TimelineDivergenceReport(input: Agent24TimelineDivergenceInput): Agent24TimelineDivergenceReport {
  const branches = input.registry.entries.filter(e => e.status === 'branch' || e.status === 'simulated');
  const main = input.registry.entries.find(e => e.status === 'main');
  const metrics: Agent24BranchDivergenceMetric[] = [];

  for (let i = 0; i < branches.length; i++) {
    for (let j = i + 1; j < branches.length; j++) {
      const a = branches[i];
      const b = branches[j];
      const turnA = a.branchTurn ?? input.branchTurnHints?.[a.branchedAtNodeId ?? ''] ?? 0;
      const turnB = b.branchTurn ?? input.branchTurnHints?.[b.branchedAtNodeId ?? ''] ?? 0;
      const divergenceTurnEstimate = Math.min(turnA, turnB);
      metrics.push({
        timelineAId: a.timelineId,
        timelineBId: b.timelineId,
        divergenceTurnEstimate,
        branchLabelDelta: `${a.label} vs ${b.label}`,
        fingerprint: o6kAgent24Fingerprint('branch_divergence', { a: a.timelineId, b: b.timelineId, divergenceTurnEstimate }),
      });
    }
  }

  if (main && branches.length > 0) {
    for (const br of branches) {
      const turnB = br.branchTurn ?? input.branchTurnHints?.[br.branchedAtNodeId ?? ''] ?? 0;
      metrics.push({
        timelineAId: main.timelineId,
        timelineBId: br.timelineId,
        divergenceTurnEstimate: turnB,
        branchLabelDelta: `main vs ${br.label}`,
        fingerprint: o6kAgent24Fingerprint('main_branch_divergence', { main: main.timelineId, br: br.timelineId, turnB }),
      });
    }
  }

  metrics.sort((x, y) => x.timelineAId.localeCompare(y.timelineAId) || x.timelineBId.localeCompare(y.timelineBId));
  const maxDivergenceTurn = metrics.reduce((m, r) => Math.max(m, r.divergenceTurnEstimate), 0);
  const payload = metrics.map(m => m.fingerprint);

  return {
    reportId: o6kAgent24Fingerprint('divergence_report', { matchId: input.matchId, count: metrics.length }),
    matchId: input.matchId,
    pairCount: metrics.length,
    metrics,
    maxDivergenceTurn,
    deterministicFingerprint: o6kAgent24Fingerprint('divergence_report_body', payload),
  };
}


// --- source: history-rollups.ts ---

export interface Agent24HistoryWindowRollup {
  windowId: string;
  fromTurn: number;
  toTurn: number;
  milestoneHitCount: number;
  milestoneWeightSum: number;
  replayEventCount: number;
  fingerprint: string;
}

export interface Agent24HistoryRollupInput {
  matchId: string;
  snapshot: O6kHistoricalAnalyticsSnapshot;
  windowSize?: number;
}

export interface Agent24HistoryRollupReport {
  reportId: string;
  matchId: string;
  windowSize: number;
  windows: Agent24HistoryWindowRollup[];
  totalMilestoneWeight: number;
  deterministicFingerprint: string;
}

export function buildAgent24HistoryRollupReport(input: Agent24HistoryRollupInput): Agent24HistoryRollupReport {
  const windowSize = input.windowSize && input.windowSize > 0 ? input.windowSize : 10;
  const maxTurn = input.snapshot.generatedAtTurn;
  const windows: Agent24HistoryWindowRollup[] = [];

  for (let from = 1; from <= maxTurn; from += windowSize) {
    const to = Math.min(maxTurn, from + windowSize - 1);
    const hits = input.snapshot.milestoneHits.filter(h => h.turn >= from && h.turn <= to);
    const weightSum = hits.reduce((s, h) => s + h.weight, 0);
    windows.push({
      windowId: o6kAgent24Fingerprint('history_window', { from, to }),
      fromTurn: from,
      toTurn: to,
      milestoneHitCount: hits.length,
      milestoneWeightSum: weightSum,
      replayEventCount: input.snapshot.integrity.replayEventCount,
      fingerprint: o6kAgent24Fingerprint('history_window_body', { from, to, count: hits.length, weightSum }),
    });
  }

  const totalMilestoneWeight = windows.reduce((s, w) => s + w.milestoneWeightSum, 0);
  const payload = windows.map(w => w.fingerprint);

  return {
    reportId: o6kAgent24Fingerprint('history_rollup', { matchId: input.matchId, windows: windows.length }),
    matchId: input.matchId,
    windowSize,
    windows,
    totalMilestoneWeight,
    deterministicFingerprint: o6kAgent24Fingerprint('history_rollup_body', payload),
  };
}


// --- source: replay-attestation.ts ---

export interface Agent24ReplayAttestationInput {
  twinBuildPassed: boolean;
  compositeFingerprint: string;
  snapshot: O6kHistoricalAnalyticsSnapshot;
  causalIndex: Agent24CausalRecordIndex;
  auditTrail: Agent24AuditTrail;
  multiSession: Agent24MultiSessionContinuity;
  analyticsDepth: Agent24ReplayAnalyticsDepth;
  scenarioSuite: Agent24ReplayScenarioSuiteResult;
}

export type Agent24AttestationStatus = 'verified' | 'degraded' | 'failed';

export interface Agent24ReplayAttestation {
  attestationId: string;
  matchId: string;
  turn: number;
  status: Agent24AttestationStatus;
  twinBuildPassed: boolean;
  integrityScore: number;
  scenarioSatisfiedRatio: number;
  resumeSafe: boolean;
  chainRoot: string;
  chainTip: string;
  deterministicFingerprint: string;
}

function ratio(n: number, d: number): number {
  if (d <= 0) return 0;
  return Math.round((n / d) * 100) / 100;
}

export function buildAgent24ReplayAttestation(bundle: Agent24ReplayAttestationInput): Agent24ReplayAttestation {
  const satisfied = bundle.scenarioSuite.satisfiedCount;
  const total = bundle.scenarioSuite.assessments.length;
  const scenarioSatisfiedRatio = ratio(satisfied, total);
  let status: Agent24AttestationStatus = 'verified';
  if (!bundle.twinBuildPassed) status = 'failed';
  else if (bundle.analyticsDepth.integrityScore < 70 || !bundle.multiSession.resumeSafe) status = 'degraded';

  const chainLinks = [
    bundle.snapshot.integrity.fingerprint,
    bundle.causalIndex.deterministicFingerprint,
    bundle.auditTrail.deterministicFingerprint,
    bundle.multiSession.deterministicFingerprint,
    bundle.compositeFingerprint,
  ];
  const chainRoot = chainLinks[0];
  let chainTip = chainRoot;
  for (let i = 1; i < chainLinks.length; i++) {
    chainTip = o6kAgent24Fingerprint('attest_link', { prev: chainTip, next: chainLinks[i] });
  }

  const payload = {
    status,
    twin: bundle.twinBuildPassed,
    integrityScore: bundle.analyticsDepth.integrityScore,
    scenarioSatisfiedRatio,
    resumeSafe: bundle.multiSession.resumeSafe,
    chainTip,
  };

  return {
    attestationId: o6kAgent24Fingerprint('replay_attestation', { matchId: bundle.snapshot.matchId, turn: bundle.snapshot.generatedAtTurn }),
    matchId: bundle.snapshot.matchId,
    turn: bundle.snapshot.generatedAtTurn,
    status,
    twinBuildPassed: bundle.twinBuildPassed,
    integrityScore: bundle.analyticsDepth.integrityScore,
    scenarioSatisfiedRatio,
    resumeSafe: bundle.multiSession.resumeSafe,
    chainRoot,
    chainTip,
    deterministicFingerprint: o6kAgent24Fingerprint('replay_attestation_body', payload),
  };
}

export function runAgent24AttestationSelfTests(): Array<{ name: string; passed: boolean; detail: string }> {
  return [
    {
      name: 'attestation_ratio_bounds',
      passed: ratio(2, 5) === 0.4 && ratio(0, 0) === 0,
      detail: 'ratio helper',
    },
  ];
}


// --- source: checkpoint-coverage.ts ---

export interface Agent24CheckpointGap {
  fromTurn: number;
  toTurn: number;
  spanTurns: number;
  severity: 'info' | 'warn' | 'critical';
  fingerprint: string;
}

export interface Agent24CheckpointCoverageReport {
  reportId: string;
  matchId: string;
  checkpointTurns: number[];
  checkpointCount: number;
  maxGapTurns: number;
  gaps: Agent24CheckpointGap[];
  endgameCoverageOk: boolean;
  coverageScore: number;
  deterministicFingerprint: string;
}

export interface Agent24CheckpointCoverageInput {
  matchId: string;
  snapshot: O6kHistoricalAnalyticsSnapshot;
  lateGame: Agent24LateGameReplayAssessment;
  maxTurns?: number;
  maxAllowedGapTurns?: number;
  checkpointTurns?: number[];
}

function gapSeverity(span: number, maxAllowed: number): Agent24CheckpointGap['severity'] {
  if (span <= maxAllowed) return 'info';
  if (span <= maxAllowed * 2) return 'warn';
  return 'critical';
}

export function buildAgent24CheckpointCoverageReport(input: Agent24CheckpointCoverageInput): Agent24CheckpointCoverageReport {
  const maxTurn = input.snapshot.generatedAtTurn;
  const maxAllowedGapTurns = input.maxAllowedGapTurns && input.maxAllowedGapTurns > 0 ? input.maxAllowedGapTurns : 12;
  const checkpointTurns = [...new Set(input.checkpointTurns || [])]
    .filter(t => Number.isFinite(t) && t >= 1 && t <= maxTurn)
    .sort((a, b) => a - b);
  const gaps: Agent24CheckpointGap[] = [];

  const anchors = [1, ...checkpointTurns, maxTurn];
  const uniqueAnchors = [...new Set(anchors)].sort((a, b) => a - b);

  for (let i = 1; i < uniqueAnchors.length; i++) {
    const fromTurn = uniqueAnchors[i - 1];
    const toTurn = uniqueAnchors[i];
    const spanTurns = toTurn - fromTurn;
    if (spanTurns <= 0) continue;
    if (spanTurns > maxAllowedGapTurns) {
      gaps.push({
        fromTurn,
        toTurn,
        spanTurns,
        severity: gapSeverity(spanTurns, maxAllowedGapTurns),
        fingerprint: o6kAgent24Fingerprint('checkpoint_gap', { fromTurn, toTurn, spanTurns }),
      });
    }
  }

  gaps.sort((a, b) => a.fromTurn - b.fromTurn || a.toTurn - b.toTurn);
  const maxGapTurns = gaps.reduce((m, g) => Math.max(m, g.spanTurns), 0);

  const maxTurns = input.maxTurns && input.maxTurns > 0 ? input.maxTurns : 120;
  const endgameStart = Math.floor(maxTurns * 0.75);
  const endgameCoverageOk =
    !input.lateGame.isLateGame ||
    checkpointTurns.some(t => t >= endgameStart && t <= maxTurn) ||
    gaps.filter(g => g.severity === 'critical' && g.toTurn >= endgameStart).length === 0;

  const criticalCount = gaps.filter(g => g.severity === 'critical').length;
  const warnCount = gaps.filter(g => g.severity === 'warn').length;
  let coverageScore = 100;
  coverageScore -= criticalCount * 25;
  coverageScore -= warnCount * 8;
  if (!endgameCoverageOk) coverageScore -= 15;
  coverageScore = Math.max(0, Math.min(100, coverageScore));

  const payload = {
    checkpoints: checkpointTurns,
    gaps: gaps.map(g => g.fingerprint),
    endgameCoverageOk,
    coverageScore,
  };

  return {
    reportId: o6kAgent24Fingerprint('checkpoint_coverage', { matchId: input.matchId, turn: maxTurn }),
    matchId: input.matchId,
    checkpointTurns,
    checkpointCount: checkpointTurns.length,
    maxGapTurns,
    gaps,
    endgameCoverageOk,
    coverageScore,
    deterministicFingerprint: o6kAgent24Fingerprint('checkpoint_coverage_body', payload),
  };
}

export function extractAgent24CheckpointTurnsFromReplay(replay?: {
  events?: Array<Record<string, unknown>>;
  checkpoints?: Record<string, unknown>;
} | null): number[] {
  const turns: number[] = [];
  for (const key of Object.keys(replay?.checkpoints || {})) {
    const n = Number.parseInt(key, 10);
    if (Number.isFinite(n)) turns.push(n);
  }
  for (const evt of replay?.events || []) {
    const type = String(evt?.eventType || '').toLowerCase();
    if (type.includes('checkpoint')) {
      const turn = Number(evt?.turn ?? evt?.day);
      if (Number.isFinite(turn)) turns.push(turn);
    }
  }
  return [...new Set(turns)].sort((a, b) => a - b);
}

export function runAgent24CheckpointCoverageSelfTests(): Array<{ name: string; passed: boolean; detail: string }> {
  const late = {
    isLateGame: false,
    requiresEndgameCheckpoint: false,
    fingerprint: 'x',
    phase: 'opening' as const,
    recommendedCheckpointKinds: ['turn'],
  };
  const snap = {
    matchId: 't',
    generatedAtTurn: 20,
    integrity: { replayEventCount: 2, checkpointCount: 2, fingerprint: 'i', deterministicMode: true },
    milestoneHits: [],
  } as O6kHistoricalAnalyticsSnapshot;
  const report = buildAgent24CheckpointCoverageReport({
    matchId: 't',
    snapshot: snap,
    lateGame: late,
    maxAllowedGapTurns: 6,
    checkpointTurns: [5, 15],
  });
  return [
    {
      name: 'checkpoint_coverage_counts',
      passed: report.checkpointCount >= 2 && report.coverageScore >= 0,
      detail: 'basic coverage report',
    },
  ];
}


// --- source: rewind-safety.ts ---

export interface Agent24RewindTarget {
  turn: number;
  source: 'checkpoint' | 'branch_fork' | 'session_boundary' | 'audit_anchor';
  label: string;
  safe: boolean;
  fingerprint: string;
}

export interface Agent24RewindSafetyReport {
  reportId: string;
  matchId: string;
  currentTurn: number;
  targets: Agent24RewindTarget[];
  safeTargetCount: number;
  recommendedTurn: number | null;
  deterministicFingerprint: string;
}

export interface Agent24RewindSafetyInput {
  matchId: string;
  currentTurn: number;
  registry: Agent24TimelineRegistry;
  auditTrail: Agent24AuditTrail;
  checkpointCoverage: Agent24CheckpointCoverageReport;
}

function isAuditSafeTurn(trail: Agent24AuditTrail, turn: number): boolean {
  const after = trail.entries.filter(e => e.turn > turn);
  const blocked = after.some(e => e.action === 'timeline_merged' || e.action === 'branch_switched');
  return !blocked;
}

export function buildAgent24RewindSafetyReport(input: Agent24RewindSafetyInput): Agent24RewindSafetyReport {
  const targets: Agent24RewindTarget[] = [];

  for (const turn of input.checkpointCoverage.checkpointTurns) {
    if (turn >= input.currentTurn) continue;
    const safe = isAuditSafeTurn(input.auditTrail, turn);
    targets.push({
      turn,
      source: 'checkpoint',
      label: `Checkpoint @ turn ${turn}`,
      safe,
      fingerprint: o6kAgent24Fingerprint('rewind_checkpoint', { turn, safe }),
    });
  }

  for (const entry of input.registry.entries) {
    const forkTurn = entry.branchTurn;
    if (forkTurn == null || forkTurn >= input.currentTurn) continue;
    const safe = isAuditSafeTurn(input.auditTrail, forkTurn);
    targets.push({
      turn: forkTurn,
      source: 'branch_fork',
      label: `Branch fork ${entry.label}`,
      safe,
      fingerprint: o6kAgent24Fingerprint('rewind_branch', { timeline: entry.timelineId, forkTurn, safe }),
    });
  }

  for (const entry of input.auditTrail.entries) {
    if (entry.action !== 'session_saved' && entry.action !== 'replay_checkpoint') continue;
    if (entry.turn >= input.currentTurn) continue;
    const safe = isAuditSafeTurn(input.auditTrail, entry.turn);
    targets.push({
      turn: entry.turn,
      source: entry.action === 'session_saved' ? 'session_boundary' : 'audit_anchor',
      label: entry.summary.slice(0, 80),
      safe,
      fingerprint: o6kAgent24Fingerprint('rewind_audit', { seq: entry.sequence, turn: entry.turn, safe }),
    });
  }

  const dedup = new Map<number, Agent24RewindTarget>();
  for (const t of targets.sort((a, b) => a.turn - b.turn || a.source.localeCompare(b.source))) {
    const existing = dedup.get(t.turn);
    if (!existing || (t.safe && !existing.safe)) dedup.set(t.turn, t);
  }
  const merged = [...dedup.values()].sort((a, b) => a.turn - b.turn || a.fingerprint.localeCompare(b.fingerprint));
  const safeTargets = merged.filter(t => t.safe);
  const recommendedTurn = safeTargets.length > 0 ? safeTargets[safeTargets.length - 1].turn : null;

  return {
    reportId: o6kAgent24Fingerprint('rewind_safety', { matchId: input.matchId, turn: input.currentTurn }),
    matchId: input.matchId,
    currentTurn: input.currentTurn,
    targets: merged,
    safeTargetCount: safeTargets.length,
    recommendedTurn,
    deterministicFingerprint: o6kAgent24Fingerprint('rewind_safety_body', merged.map(t => t.fingerprint)),
  };
}


// --- source: history-reconciliation.ts ---

export interface Agent24SessionReconciliationIssue {
  sessionId: string;
  kind: 'missing_save' | 'missing_resume' | 'turn_overlap' | 'attestation_mismatch';
  detail: string;
  fingerprint: string;
}

export interface Agent24HistoryReconciliationReport {
  reportId: string;
  matchId: string;
  sessionCount: number;
  issueCount: number;
  issues: Agent24SessionReconciliationIssue[];
  reconciled: boolean;
  reconciliationScore: number;
  deterministicFingerprint: string;
}

export interface Agent24HistoryReconciliationInput {
  matchId: string;
  multiSession: Agent24MultiSessionContinuity;
  auditTrail: Agent24AuditTrail;
  attestation: Agent24ReplayAttestation;
}

export function buildAgent24HistoryReconciliationReport(
  input: Agent24HistoryReconciliationInput,
): Agent24HistoryReconciliationReport {
  const issues: Agent24SessionReconciliationIssue[] = [];
  const savesBySession = new Map<string, number>();
  const resumesBySession = new Map<string, number>();

  for (const entry of input.auditTrail.entries) {
    const sid = entry.relatedSessionId;
    if (!sid) continue;
    if (entry.action === 'session_saved') savesBySession.set(sid, (savesBySession.get(sid) || 0) + 1);
    if (entry.action === 'session_resumed') resumesBySession.set(sid, (resumesBySession.get(sid) || 0) + 1);
  }

  for (const session of input.multiSession.sessions) {
    const saves = savesBySession.get(session.sessionId) || 0;
    const resumes = resumesBySession.get(session.sessionId) || 0;
    if (
      input.multiSession.sessionCount > 1 &&
      saves === 0 &&
      session.endedAtTurn > session.startedAtTurn
    ) {
      issues.push({
        sessionId: session.sessionId,
        kind: 'missing_save',
        detail: `Session ${session.sessionId} ended without session_saved audit`,
        fingerprint: o6kAgent24Fingerprint('recon_missing_save', { sessionId: session.sessionId }),
      });
    }
    if (resumes === 0 && input.multiSession.sessionCount > 1 && session.sessionId !== input.multiSession.sessions[0]?.sessionId) {
      issues.push({
        sessionId: session.sessionId,
        kind: 'missing_resume',
        detail: `Follow-on session ${session.sessionId} lacks session_resumed audit`,
        fingerprint: o6kAgent24Fingerprint('recon_missing_resume', { sessionId: session.sessionId }),
      });
    }
  }

  if (!input.multiSession.resumeSafe) {
    issues.push({
      sessionId: '_overlap',
      kind: 'turn_overlap',
      detail: 'Multi-session continuity flagged overlapping turn ranges',
      fingerprint: o6kAgent24Fingerprint('recon_overlap', { resumeSafe: false }),
    });
  }

  if (input.attestation.status === 'failed') {
    issues.push({
      sessionId: '_attest',
      kind: 'attestation_mismatch',
      detail: 'Replay attestation failed while sessions present',
      fingerprint: o6kAgent24Fingerprint('recon_attest_failed', { status: input.attestation.status }),
    });
  }

  issues.sort((a, b) => a.sessionId.localeCompare(b.sessionId) || a.kind.localeCompare(b.kind));
  const issueCount = issues.length;
  let reconciliationScore = 100;
  reconciliationScore -= issueCount * 12;
  reconciliationScore = Math.max(0, Math.min(100, reconciliationScore));
  const reconciled = issueCount === 0 && input.multiSession.resumeSafe && input.attestation.status !== 'failed';

  return {
    reportId: o6kAgent24Fingerprint('history_reconciliation', { matchId: input.matchId, sessions: input.multiSession.sessionCount }),
    matchId: input.matchId,
    sessionCount: input.multiSession.sessionCount,
    issueCount,
    issues,
    reconciled,
    reconciliationScore,
    deterministicFingerprint: o6kAgent24Fingerprint('history_reconciliation_body', {
      issues: issues.map(i => i.fingerprint),
      reconciled,
      reconciliationScore,
    }),
  };
}


// --- source: replay-playback-integrity.ts ---

export interface Agent24ReplayEventLike {
  eventType?: string;
  turn?: number;
  sequence?: number;
  day?: number;
}

export interface Agent24ReplayPlaybackIssue {
  kind: 'turn_regression' | 'duplicate_checkpoint' | 'sequence_gap' | 'missing_turn';
  turn: number;
  detail: string;
  severity: 'info' | 'warn' | 'critical';
  fingerprint: string;
}

export interface Agent24ReplayPlaybackIntegrityReport {
  reportId: string;
  matchId: string;
  eventCount: number;
  checkpointEventCount: number;
  issueCount: number;
  issues: Agent24ReplayPlaybackIssue[];
  monotonicTurns: boolean;
  integrityScore: number;
  deterministicFingerprint: string;
}

export interface Agent24ReplayPlaybackIntegrityInput {
  matchId: string;
  currentTurn: number;
  replay?: {
    events?: Agent24ReplayEventLike[];
    checkpoints?: Record<string, unknown>;
  } | null;
}

function issueSeverity(kind: Agent24ReplayPlaybackIssue['kind']): Agent24ReplayPlaybackIssue['severity'] {
  if (kind === 'turn_regression') return 'critical';
  if (kind === 'duplicate_checkpoint') return 'warn';
  if (kind === 'sequence_gap') return 'warn';
  return 'info';
}

export function buildAgent24ReplayPlaybackIntegrityReport(
  input: Agent24ReplayPlaybackIntegrityInput,
): Agent24ReplayPlaybackIntegrityReport {
  const events = [...(input.replay?.events || [])].sort((a, b) => {
    const sa = a.sequence ?? a.turn ?? 0;
    const sb = b.sequence ?? b.turn ?? 0;
    return sa - sb || (a.turn ?? 0) - (b.turn ?? 0);
  });

  const issues: Agent24ReplayPlaybackIssue[] = [];
  let lastTurn = 0;
  let lastSequence: number | null = null;
  const checkpointTurnsSeen = new Set<number>();

  for (const ev of events) {
    const turn = typeof ev.turn === 'number' ? ev.turn : 0;
    const seq = typeof ev.sequence === 'number' ? ev.sequence : null;

    if (turn > 0 && turn < lastTurn) {
      issues.push({
        kind: 'turn_regression',
        turn,
        detail: `Replay event turn ${turn} regresses from prior turn ${lastTurn}`,
        severity: issueSeverity('turn_regression'),
        fingerprint: o6kAgent24Fingerprint('playback_regression', { turn, lastTurn }),
      });
    }
    if (turn > lastTurn) lastTurn = turn;

    if (seq != null && lastSequence != null && seq > lastSequence + 1) {
      issues.push({
        kind: 'sequence_gap',
        turn,
        detail: `Sequence jumped from ${lastSequence} to ${seq}`,
        severity: issueSeverity('sequence_gap'),
        fingerprint: o6kAgent24Fingerprint('playback_seq_gap', { from: lastSequence, to: seq }),
      });
    }
    if (seq != null) lastSequence = seq;

    if (ev.eventType === 'replay_checkpoint' && turn > 0) {
      if (checkpointTurnsSeen.has(turn)) {
        issues.push({
          kind: 'duplicate_checkpoint',
          turn,
          detail: `Duplicate replay_checkpoint at turn ${turn}`,
          severity: issueSeverity('duplicate_checkpoint'),
          fingerprint: o6kAgent24Fingerprint('playback_dup_ckpt', { turn }),
        });
      }
      checkpointTurnsSeen.add(turn);
    }
  }

  const checkpointKeys = Object.keys(input.replay?.checkpoints || {})
    .map(k => Number(k))
    .filter(n => Number.isFinite(n) && n >= 1);
  for (const ck of checkpointKeys) {
    if (!checkpointTurnsSeen.has(ck) && ck <= input.currentTurn) {
      issues.push({
        kind: 'missing_turn',
        turn: ck,
        detail: `Checkpoint map includes turn ${ck} without matching replay_checkpoint event`,
        severity: 'info',
        fingerprint: o6kAgent24Fingerprint('playback_ckpt_orphan', { turn: ck }),
      });
    }
  }

  issues.sort((a, b) => a.turn - b.turn || a.kind.localeCompare(b.kind));
  const criticalCount = issues.filter(i => i.severity === 'critical').length;
  const warnCount = issues.filter(i => i.severity === 'warn').length;
  let integrityScore = 100;
  integrityScore -= criticalCount * 30;
  integrityScore -= warnCount * 10;
  integrityScore -= issues.filter(i => i.severity === 'info').length * 3;
  integrityScore = Math.max(0, Math.min(100, integrityScore));
  const monotonicTurns = criticalCount === 0;

  const checkpointEventCount = events.filter(e => e.eventType === 'replay_checkpoint').length;

  return {
    reportId: o6kAgent24Fingerprint('playback_integrity', { matchId: input.matchId, turn: input.currentTurn }),
    matchId: input.matchId,
    eventCount: events.length,
    checkpointEventCount,
    issueCount: issues.length,
    issues,
    monotonicTurns,
    integrityScore,
    deterministicFingerprint: o6kAgent24Fingerprint('playback_integrity_body', {
      issues: issues.map(i => i.fingerprint),
      monotonicTurns,
      integrityScore,
    }),
  };
}

export function runAgent24PlaybackIntegritySelfTests(): Array<{ name: string; passed: boolean }> {
  const clean = buildAgent24ReplayPlaybackIntegrityReport({
    matchId: 'self',
    currentTurn: 10,
    replay: {
      events: [
        { eventType: 'replay_checkpoint', turn: 4, sequence: 1 },
        { eventType: 'replay_checkpoint', turn: 10, sequence: 2 },
      ],
      checkpoints: { '4': {}, '10': {} },
    },
  });
  const dirty = buildAgent24ReplayPlaybackIntegrityReport({
    matchId: 'self',
    currentTurn: 10,
    replay: {
      events: [
        { eventType: 'replay_checkpoint', turn: 8, sequence: 1 },
        { eventType: 'replay_checkpoint', turn: 5, sequence: 2 },
      ],
    },
  });
  return [
    { name: 'clean_monotonic', passed: clean.monotonicTurns && clean.integrityScore >= 90 },
    { name: 'regression_detected', passed: !dirty.monotonicTurns && dirty.issues.some(i => i.kind === 'turn_regression') },
    {
      name: 'deterministic_fingerprint',
      passed:
        clean.deterministicFingerprint ===
        buildAgent24ReplayPlaybackIntegrityReport({
          matchId: 'self',
          currentTurn: 10,
          replay: clean.eventCount
            ? {
                events: [
                  { eventType: 'replay_checkpoint', turn: 4, sequence: 1 },
                  { eventType: 'replay_checkpoint', turn: 10, sequence: 2 },
                ],
                checkpoints: { '4': {}, '10': {} },
              }
            : undefined,
        }).deterministicFingerprint,
    },
  ];
}


// --- source: branch-lineage.ts ---

export interface Agent24BranchLineageNode {
  nodeId: string;
  parentNodeId: string | null;
  branchTurn: number | null;
  depthFromRoot: number;
  lineagePath: string[];
  label: string;
  fingerprint: string;
}

export interface Agent24BranchLineageReport {
  reportId: string;
  matchId: string;
  nodeCount: number;
  maxDepth: number;
  deepestNodeId: string | null;
  nodes: Agent24BranchLineageNode[];
  deterministicFingerprint: string;
}

export interface Agent24BranchLineageInput {
  matchId: string;
  registry: Agent24TimelineRegistry;
  nodesById?: Record<string, Agent24TimelineBranchNodeLike>;
}

export function buildAgent24BranchLineageReport(input: Agent24BranchLineageInput): Agent24BranchLineageReport {
  const nodesById = input.nodesById || {};
  const nodeIds = new Set<string>(['root', ...input.registry.branchNodeOrder, ...Object.keys(nodesById)]);

  const meta = new Map<string, Agent24TimelineBranchNodeLike & { label: string }>();
  meta.set('root', { nodeId: 'root', label: 'Main timeline root', branchTurn: 1 });
  for (const nodeId of nodeIds) {
    if (nodeId === 'root') continue;
    const raw = nodesById[nodeId];
    const fromEntry = input.registry.entries.find(e => e.branchedAtNodeId === nodeId);
    meta.set(nodeId, {
      nodeId,
      parentNodeId: raw?.parentNodeId ?? 'root',
      branchTurn: raw?.branchTurn ?? fromEntry?.branchTurn ?? undefined,
      label: raw?.label || fromEntry?.label || nodeId,
    });
  }

  const lineageCache = new Map<string, string[]>();
  function lineagePath(nodeId: string): string[] {
    const cached = lineageCache.get(nodeId);
    if (cached) return cached;
    if (nodeId === 'root') {
      lineageCache.set(nodeId, ['root']);
      return ['root'];
    }
    const info = meta.get(nodeId);
    const parent = info?.parentNodeId && info.parentNodeId !== nodeId ? info.parentNodeId : 'root';
    const path = [...lineagePath(parent), nodeId];
    lineageCache.set(nodeId, path);
    return path;
  }

  const nodes: Agent24BranchLineageNode[] = [];
  for (const nodeId of [...nodeIds].sort()) {
    const info = meta.get(nodeId)!;
    const path = lineagePath(nodeId);
    const depthFromRoot = Math.max(0, path.length - 1);
    nodes.push({
      nodeId,
      parentNodeId: nodeId === 'root' ? null : info.parentNodeId ?? 'root',
      branchTurn: info.branchTurn ?? null,
      depthFromRoot,
      lineagePath: path,
      label: info.label,
      fingerprint: o6kAgent24Fingerprint('branch_lineage_node', { nodeId, depthFromRoot, path }),
    });
  }

  nodes.sort((a, b) => a.depthFromRoot - b.depthFromRoot || a.nodeId.localeCompare(b.nodeId));
  const maxDepth = nodes.reduce((m, n) => Math.max(m, n.depthFromRoot), 0);
  const deepest = nodes.filter(n => n.depthFromRoot === maxDepth).sort((a, b) => a.nodeId.localeCompare(b.nodeId))[0];

  return {
    reportId: o6kAgent24Fingerprint('branch_lineage', { matchId: input.matchId, nodes: nodes.length }),
    matchId: input.matchId,
    nodeCount: nodes.length,
    maxDepth,
    deepestNodeId: deepest?.nodeId ?? null,
    nodes,
    deterministicFingerprint: o6kAgent24Fingerprint('branch_lineage_body', nodes.map(n => n.fingerprint)),
  };
}


// --- source: export-readiness.ts ---

export type Agent24ExportBlockerKind =
  | 'attestation'
  | 'reconciliation'
  | 'checkpoint_coverage'
  | 'playback_integrity'
  | 'rewind_safety';

export interface Agent24ExportReadinessBlocker {
  kind: Agent24ExportBlockerKind;
  detail: string;
  fingerprint: string;
}

export interface Agent24ExportReadinessReport {
  reportId: string;
  matchId: string;
  ready: boolean;
  readinessScore: number;
  blockerCount: number;
  blockers: Agent24ExportReadinessBlocker[];
  deterministicFingerprint: string;
}

export interface Agent24ExportReadinessInput {
  matchId: string;
  attestation: Agent24ReplayAttestation;
  historyReconciliation: Agent24HistoryReconciliationReport;
  checkpointCoverage: Agent24CheckpointCoverageReport;
  playbackIntegrity: Agent24ReplayPlaybackIntegrityReport;
  rewindSafety: Agent24RewindSafetyReport;
  minCoverageScore?: number;
  minIntegrityScore?: number;
}

export function buildAgent24ExportReadinessReport(input: Agent24ExportReadinessInput): Agent24ExportReadinessReport {
  const minCoverage = input.minCoverageScore ?? 60;
  const minIntegrity = input.minIntegrityScore ?? 70;
  const blockers: Agent24ExportReadinessBlocker[] = [];

  if (input.attestation.status !== 'verified') {
    blockers.push({
      kind: 'attestation',
      detail: `Attestation status is ${input.attestation.status}, expected verified`,
      fingerprint: o6kAgent24Fingerprint('export_block_attest', { status: input.attestation.status }),
    });
  }
  if (!input.historyReconciliation.reconciled) {
    blockers.push({
      kind: 'reconciliation',
      detail: `History reconciliation open (${input.historyReconciliation.issueCount} issues)`,
      fingerprint: o6kAgent24Fingerprint('export_block_recon', { issues: input.historyReconciliation.issueCount }),
    });
  }
  if (input.checkpointCoverage.coverageScore < minCoverage) {
    blockers.push({
      kind: 'checkpoint_coverage',
      detail: `Checkpoint coverage score ${input.checkpointCoverage.coverageScore} below ${minCoverage}`,
      fingerprint: o6kAgent24Fingerprint('export_block_coverage', { score: input.checkpointCoverage.coverageScore }),
    });
  }
  if (!input.playbackIntegrity.monotonicTurns || input.playbackIntegrity.integrityScore < minIntegrity) {
    blockers.push({
      kind: 'playback_integrity',
      detail: `Playback integrity score ${input.playbackIntegrity.integrityScore} (monotonic=${input.playbackIntegrity.monotonicTurns})`,
      fingerprint: o6kAgent24Fingerprint('export_block_playback', {
        score: input.playbackIntegrity.integrityScore,
        monotonic: input.playbackIntegrity.monotonicTurns,
      }),
    });
  }
  if (input.rewindSafety.safeTargetCount === 0) {
    blockers.push({
      kind: 'rewind_safety',
      detail: 'No safe rewind targets — export may not be replayable',
      fingerprint: o6kAgent24Fingerprint('export_block_rewind', { safe: 0 }),
    });
  }

  blockers.sort((a, b) => a.kind.localeCompare(b.kind));
  let readinessScore = 100;
  readinessScore -= blockers.length * 18;
  readinessScore = Math.max(0, Math.min(100, readinessScore));
  const ready = blockers.length === 0;

  return {
    reportId: o6kAgent24Fingerprint('export_readiness', { matchId: input.matchId, ready }),
    matchId: input.matchId,
    ready,
    readinessScore,
    blockerCount: blockers.length,
    blockers,
    deterministicFingerprint: o6kAgent24Fingerprint('export_readiness_body', {
      blockers: blockers.map(b => b.fingerprint),
      ready,
      readinessScore,
    }),
  };
}


// --- source: export-manifest.ts ---

export type Agent24ExportManifestSectionKind =
  | 'attestation'
  | 'export_readiness'
  | 'branch_lineage'
  | 'composite_bundle';

export interface Agent24ExportManifestSection {
  kind: Agent24ExportManifestSectionKind;
  label: string;
  fingerprint: string;
  required: boolean;
}

export interface Agent24ExportManifest {
  manifestId: string;
  matchId: string;
  sectionCount: number;
  requiredSectionCount: number;
  sections: Agent24ExportManifestSection[];
  compositeBundleFingerprint: string;
  complete: boolean;
  deterministicFingerprint: string;
}

export interface Agent24ExportManifestInput {
  matchId: string;
  attestation: Agent24ReplayAttestation;
  exportReadiness: Agent24ExportReadinessReport;
  branchLineage: Agent24BranchLineageReport;
  compositeBundleFingerprint: string;
}

export function buildAgent24ExportManifest(input: Agent24ExportManifestInput): Agent24ExportManifest {
  const sections: Agent24ExportManifestSection[] = [
    {
      kind: 'attestation',
      label: 'Replay attestation',
      fingerprint: input.attestation.deterministicFingerprint,
      required: true,
    },
    {
      kind: 'export_readiness',
      label: 'Export readiness gate',
      fingerprint: input.exportReadiness.deterministicFingerprint,
      required: true,
    },
    {
      kind: 'branch_lineage',
      label: 'Branch lineage map',
      fingerprint: input.branchLineage.deterministicFingerprint,
      required: input.branchLineage.nodeCount > 1,
    },
    {
      kind: 'composite_bundle',
      label: 'Composite determinism bundle',
      fingerprint: input.compositeBundleFingerprint,
      required: true,
    },
  ];

  sections.sort((a, b) => a.kind.localeCompare(b.kind));
  const requiredSectionCount = sections.filter(s => s.required).length;
  const complete = sections.every(s => !s.required || s.fingerprint.length > 0);

  return {
    manifestId: o6kAgent24Fingerprint('export_manifest', { matchId: input.matchId, sections: sections.length }),
    matchId: input.matchId,
    sectionCount: sections.length,
    requiredSectionCount,
    sections,
    compositeBundleFingerprint: input.compositeBundleFingerprint,
    complete,
    deterministicFingerprint: o6kAgent24Fingerprint('export_manifest_body', {
      sections: sections.map(s => ({ kind: s.kind, fp: s.fingerprint, req: s.required })),
      complete,
    }),
  };
}

export function runAgent24ExportManifestSelfTests(): Array<{ name: string; passed: boolean }> {
  const attestationFp = o6kAgent24Fingerprint('test_attest', { ok: 1 });
  const readinessFp = o6kAgent24Fingerprint('test_ready', { ok: 1 });
  const lineageFp = o6kAgent24Fingerprint('test_lineage', { ok: 1 });
  const composite = o6kAgent24Fingerprint('test_composite', { ok: 1 });
  const input = {
    matchId: 'self',
    attestation: {
      attestationId: 'a',
      matchId: 'self',
      turn: 1,
      status: 'verified' as const,
      twinBuildPassed: true,
      integrityScore: 90,
      scenarioSatisfiedRatio: 1,
      resumeSafe: true,
      chainRoot: 'r',
      chainTip: 't',
      deterministicFingerprint: attestationFp,
    },
    exportReadiness: {
      reportId: 'r',
      matchId: 'self',
      ready: true,
      readinessScore: 100,
      blockerCount: 0,
      blockers: [],
      deterministicFingerprint: readinessFp,
    },
    branchLineage: {
      reportId: 'l',
      matchId: 'self',
      nodeCount: 1,
      maxDepth: 0,
      deepestNodeId: 'root',
      nodes: [],
      deterministicFingerprint: lineageFp,
    },
    compositeBundleFingerprint: composite,
  };
  const manifest = buildAgent24ExportManifest(input);
  const twin = buildAgent24ExportManifest(input);
  return [
    { name: 'manifest_complete', passed: manifest.complete && manifest.sectionCount >= 3 },
    { name: 'deterministic_fingerprint', passed: manifest.deterministicFingerprint === twin.deterministicFingerprint },
  ];
}


// --- source: import-validation.ts ---

export type Agent24ImportValidationIssueKind =
  | 'manifest_incomplete'
  | 'fingerprint_mismatch'
  | 'export_not_ready'
  | 'attestation_not_verified';

export interface Agent24ImportValidationIssue {
  kind: Agent24ImportValidationIssueKind;
  detail: string;
  fingerprint: string;
}

export interface Agent24ImportValidationReport {
  reportId: string;
  matchId: string;
  valid: boolean;
  issueCount: number;
  issues: Agent24ImportValidationIssue[];
  validationScore: number;
  deterministicFingerprint: string;
}

export interface Agent24ImportValidationInput {
  matchId: string;
  manifest: Agent24ExportManifest;
  attestation: Agent24ReplayAttestation;
  exportReadiness: Agent24ExportReadinessReport;
  expectedCompositeFingerprint: string;
}

export function buildAgent24ImportValidationReport(input: Agent24ImportValidationInput): Agent24ImportValidationReport {
  const issues: Agent24ImportValidationIssue[] = [];

  if (!input.manifest.complete) {
    issues.push({
      kind: 'manifest_incomplete',
      detail: 'Export manifest missing required section fingerprints',
      fingerprint: o6kAgent24Fingerprint('import_manifest_incomplete', { complete: false }),
    });
  }
  if (input.manifest.compositeBundleFingerprint !== input.expectedCompositeFingerprint) {
    issues.push({
      kind: 'fingerprint_mismatch',
      detail: 'Manifest composite fingerprint does not match live bundle',
      fingerprint: o6kAgent24Fingerprint('import_fp_mismatch', {
        manifest: input.manifest.compositeBundleFingerprint,
        live: input.expectedCompositeFingerprint,
      }),
    });
  }
  if (!input.exportReadiness.ready) {
    issues.push({
      kind: 'export_not_ready',
      detail: `Export readiness blocked (${input.exportReadiness.blockerCount} blockers)`,
      fingerprint: o6kAgent24Fingerprint('import_not_ready', { blockers: input.exportReadiness.blockerCount }),
    });
  }
  if (input.attestation.status !== 'verified') {
    issues.push({
      kind: 'attestation_not_verified',
      detail: `Attestation status ${input.attestation.status}`,
      fingerprint: o6kAgent24Fingerprint('import_attest', { status: input.attestation.status }),
    });
  }

  const attestationSection = input.manifest.sections.find(s => s.kind === 'attestation');
  if (attestationSection && attestationSection.fingerprint !== input.attestation.deterministicFingerprint) {
    issues.push({
      kind: 'fingerprint_mismatch',
      detail: 'Manifest attestation section fingerprint stale',
      fingerprint: o6kAgent24Fingerprint('import_attest_fp', { stale: true }),
    });
  }

  issues.sort((a, b) => a.kind.localeCompare(b.kind));
  let validationScore = 100;
  validationScore -= issues.length * 22;
  validationScore = Math.max(0, Math.min(100, validationScore));
  const valid = issues.length === 0;

  return {
    reportId: o6kAgent24Fingerprint('import_validation', { matchId: input.matchId, valid }),
    matchId: input.matchId,
    valid,
    issueCount: issues.length,
    issues,
    validationScore,
    deterministicFingerprint: o6kAgent24Fingerprint('import_validation_body', {
      issues: issues.map(i => i.fingerprint),
      valid,
      validationScore,
    }),
  };
}

export function runAgent24ImportValidationSelfTests(): Array<{ name: string; passed: boolean }> {
  const composite = o6kAgent24Fingerprint('import_self_composite', { v: 1 });
  const attestationFp = o6kAgent24Fingerprint('import_self_attest', { v: 1 });
  const readinessFp = o6kAgent24Fingerprint('import_self_ready', { v: 1 });
  const manifest = {
    manifestId: 'm',
    matchId: 'self',
    sectionCount: 3,
    requiredSectionCount: 3,
    sections: [
      { kind: 'attestation' as const, label: 'A', fingerprint: attestationFp, required: true },
      { kind: 'composite_bundle' as const, label: 'C', fingerprint: composite, required: true },
    ],
    compositeBundleFingerprint: composite,
    complete: true,
    deterministicFingerprint: o6kAgent24Fingerprint('import_self_manifest', { v: 1 }),
  };
  const attestation = {
    attestationId: 'a',
    matchId: 'self',
    turn: 5,
    status: 'verified' as const,
    twinBuildPassed: true,
    integrityScore: 90,
    scenarioSatisfiedRatio: 1,
    resumeSafe: true,
    chainRoot: 'r',
    chainTip: 't',
    deterministicFingerprint: attestationFp,
  };
  const readiness = {
    reportId: 'r',
    matchId: 'self',
    ready: true,
    readinessScore: 100,
    blockerCount: 0,
    blockers: [],
    deterministicFingerprint: readinessFp,
  };
  const ok = buildAgent24ImportValidationReport({
    matchId: 'self',
    manifest,
    attestation,
    exportReadiness: readiness,
    expectedCompositeFingerprint: composite,
  });
  const bad = buildAgent24ImportValidationReport({
    matchId: 'self',
    manifest,
    attestation,
    exportReadiness: readiness,
    expectedCompositeFingerprint: o6kAgent24Fingerprint('wrong', { v: 2 }),
  });
  return [
    { name: 'valid_import', passed: ok.valid && ok.validationScore >= 90 },
    { name: 'mismatch_detected', passed: !bad.valid && bad.issues.some(i => i.kind === 'fingerprint_mismatch') },
  ];
}


// --- source: history-retention.ts ---

export interface Agent24HistoryRetentionBand {
  fromTurn: number;
  toTurn: number;
  checkpointCount: number;
  pruneSafe: boolean;
  fingerprint: string;
}

export interface Agent24HistoryRetentionReport {
  reportId: string;
  matchId: string;
  currentTurn: number;
  retentionWindowTurns: number;
  pruneSafeCutoffTurn: number;
  bands: Agent24HistoryRetentionBand[];
  bandCount: number;
  retentionScore: number;
  deterministicFingerprint: string;
}

export interface Agent24HistoryRetentionInput {
  matchId: string;
  currentTurn: number;
  maxTurns?: number;
  checkpointCoverage: Agent24CheckpointCoverageReport;
  rewindSafety: Agent24RewindSafetyReport;
  bandSize?: number;
  minRetentionTurns?: number;
}

export function buildAgent24HistoryRetentionReport(input: Agent24HistoryRetentionInput): Agent24HistoryRetentionReport {
  const bandSize = input.bandSize ?? 10;
  const minRetention = input.minRetentionTurns ?? Math.max(5, Math.floor(bandSize / 2));
  const maxTurns = input.maxTurns && input.maxTurns > 0 ? input.maxTurns : Math.max(input.currentTurn, bandSize);
  const retentionWindowTurns = Math.min(maxTurns, Math.max(minRetention, input.currentTurn));

  const safeTurns = new Set(
    input.rewindSafety.targets.filter(t => t.safe).map(t => t.turn),
  );
  const checkpointTurns = new Set(input.checkpointCoverage.checkpointTurns);

  const bands: Agent24HistoryRetentionBand[] = [];
  for (let from = 1; from <= input.currentTurn; from += bandSize) {
    const to = Math.min(from + bandSize - 1, input.currentTurn);
    let checkpointCount = 0;
    for (const t of checkpointTurns) {
      if (t >= from && t <= to) checkpointCount += 1;
    }
    const hasSafeRewind = [...safeTurns].some(t => t >= from && t <= to);
    const pruneSafe = from >= retentionWindowTurns ? false : hasSafeRewind || checkpointCount > 0;
    bands.push({
      fromTurn: from,
      toTurn: to,
      checkpointCount,
      pruneSafe,
      fingerprint: o6kAgent24Fingerprint('retention_band', { from, to, checkpointCount, pruneSafe }),
    });
  }

  bands.sort((a, b) => a.fromTurn - b.fromTurn);
  const pruneSafeCutoffTurn =
    bands.filter(b => b.pruneSafe).sort((a, b) => b.toTurn - a.toTurn)[0]?.toTurn ?? 0;

  let retentionScore = 100;
  if (input.checkpointCoverage.coverageScore < 50) retentionScore -= 20;
  if (input.rewindSafety.safeTargetCount === 0) retentionScore -= 25;
  if (pruneSafeCutoffTurn < minRetention && input.currentTurn > minRetention) retentionScore -= 15;
  retentionScore = Math.max(0, Math.min(100, retentionScore));

  return {
    reportId: o6kAgent24Fingerprint('history_retention', { matchId: input.matchId, turn: input.currentTurn }),
    matchId: input.matchId,
    currentTurn: input.currentTurn,
    retentionWindowTurns,
    pruneSafeCutoffTurn,
    bands,
    bandCount: bands.length,
    retentionScore,
    deterministicFingerprint: o6kAgent24Fingerprint('history_retention_body', {
      bands: bands.map(b => b.fingerprint),
      pruneSafeCutoffTurn,
      retentionScore,
    }),
  };
}

export function runAgent24HistoryRetentionSelfTests(): Array<{ name: string; passed: boolean }> {
  const coverage = {
    reportId: 'c',
    matchId: 'self',
    checkpointTurns: [4, 8, 12],
    checkpointCount: 3,
    maxGapTurns: 4,
    gaps: [],
    endgameCoverageOk: true,
    coverageScore: 85,
    deterministicFingerprint: o6kAgent24Fingerprint('ret_self_cov', { v: 1 }),
  };
  const rewind = {
    reportId: 'w',
    matchId: 'self',
    currentTurn: 15,
    targets: [
      { turn: 8, source: 'checkpoint' as const, label: 'ckpt', safe: true, fingerprint: 'f1' },
      { turn: 12, source: 'checkpoint' as const, label: 'ckpt2', safe: true, fingerprint: 'f2' },
    ],
    safeTargetCount: 2,
    recommendedTurn: 12,
    deterministicFingerprint: o6kAgent24Fingerprint('ret_self_rewind', { v: 1 }),
  };
  const report = buildAgent24HistoryRetentionReport({
    matchId: 'self',
    currentTurn: 15,
    maxTurns: 100,
    checkpointCoverage: coverage,
    rewindSafety: rewind,
    bandSize: 5,
  });
  return [
    { name: 'bands_cover_turn_range', passed: report.bandCount >= 2 && report.pruneSafeCutoffTurn >= 8 },
    {
      name: 'deterministic_fingerprint',
      passed:
        report.deterministicFingerprint ===
        buildAgent24HistoryRetentionReport({
          matchId: 'self',
          currentTurn: 15,
          maxTurns: 100,
          checkpointCoverage: coverage,
          rewindSafety: rewind,
          bandSize: 5,
        }).deterministicFingerprint,
    },
  ];
}


// --- source: archive-compaction.ts ---

export interface Agent24ArchiveCompactionBand {
  fromTurn: number;
  toTurn: number;
  eligible: boolean;
  reason: string;
  estimatedEventSlots: number;
  fingerprint: string;
}

export interface Agent24ArchiveCompactionPlan {
  planId: string;
  matchId: string;
  currentTurn: number;
  eligibleBandCount: number;
  protectedBandCount: number;
  estimatedSlotsReclaimed: number;
  compactionSafe: boolean;
  bands: Agent24ArchiveCompactionBand[];
  compactionScore: number;
  deterministicFingerprint: string;
}

export interface Agent24ArchiveCompactionInput {
  matchId: string;
  currentTurn: number;
  historyRetention: Agent24HistoryRetentionReport;
  importValidation: Agent24ImportValidationReport;
  replayEventCount?: number;
}

export function buildAgent24ArchiveCompactionPlan(input: Agent24ArchiveCompactionInput): Agent24ArchiveCompactionPlan {
  const replayEventCount = input.replayEventCount ?? Math.max(1, input.currentTurn);
  const eventsPerTurn = Math.max(1, Math.ceil(replayEventCount / Math.max(1, input.currentTurn)));

  const bands: Agent24ArchiveCompactionBand[] = input.historyRetention.bands.map(band => {
    const eligible = !band.pruneSafe && band.toTurn < input.historyRetention.pruneSafeCutoffTurn;
    let reason = eligible ? 'outside_prune_safe_window' : 'protected_by_checkpoint_or_rewind';
    if (band.pruneSafe) reason = 'retention_band_marked_prune_safe';
    const estimatedEventSlots = eligible ? (band.toTurn - band.fromTurn + 1) * eventsPerTurn : 0;
    return {
      fromTurn: band.fromTurn,
      toTurn: band.toTurn,
      eligible,
      reason,
      estimatedEventSlots,
      fingerprint: o6kAgent24Fingerprint('archive_compaction_band', {
        from: band.fromTurn,
        to: band.toTurn,
        eligible,
        reason,
      }),
    };
  });

  bands.sort((a, b) => a.fromTurn - b.fromTurn);
  const eligibleBandCount = bands.filter(b => b.eligible).length;
  const protectedBandCount = bands.length - eligibleBandCount;
  const estimatedSlotsReclaimed = bands.reduce((sum, b) => sum + b.estimatedEventSlots, 0);

  let compactionScore = 100;
  if (input.importValidation.valid === false) compactionScore -= 35;
  if (input.historyRetention.retentionScore < 60) compactionScore -= 20;
  if (eligibleBandCount === 0 && input.currentTurn > 15) compactionScore -= 15;
  compactionScore = Math.max(0, Math.min(100, compactionScore));

  const compactionSafe =
    input.importValidation.valid &&
    input.historyRetention.pruneSafeCutoffTurn > 0 &&
    eligibleBandCount >= 0;

  return {
    planId: o6kAgent24Fingerprint('archive_compaction', { matchId: input.matchId, turn: input.currentTurn }),
    matchId: input.matchId,
    currentTurn: input.currentTurn,
    eligibleBandCount,
    protectedBandCount,
    estimatedSlotsReclaimed,
    compactionSafe,
    bands,
    compactionScore,
    deterministicFingerprint: o6kAgent24Fingerprint('archive_compaction_body', {
      bands: bands.map(b => b.fingerprint),
      eligibleBandCount,
      estimatedSlotsReclaimed,
      compactionSafe,
      compactionScore,
    }),
  };
}

export function runAgent24ArchiveCompactionSelfTests(): Array<{ name: string; passed: boolean }> {
  const retention = {
    reportId: 'r',
    matchId: 'self',
    currentTurn: 20,
    retentionWindowTurns: 20,
    pruneSafeCutoffTurn: 11,
    bands: [
      {
        fromTurn: 1,
        toTurn: 5,
        checkpointCount: 1,
        pruneSafe: true,
        fingerprint: o6kAgent24Fingerprint('rb1', { v: 1 }),
      },
      {
        fromTurn: 6,
        toTurn: 10,
        checkpointCount: 0,
        pruneSafe: false,
        fingerprint: o6kAgent24Fingerprint('rb2', { v: 1 }),
      },
      {
        fromTurn: 11,
        toTurn: 15,
        checkpointCount: 1,
        pruneSafe: true,
        fingerprint: o6kAgent24Fingerprint('rb3', { v: 1 }),
      },
    ],
    bandCount: 3,
    retentionScore: 80,
    deterministicFingerprint: o6kAgent24Fingerprint('ret_self', { v: 1 }),
  };
  const importOk = {
    reportId: 'i',
    matchId: 'self',
    valid: true,
    issueCount: 0,
    issues: [],
    validationScore: 100,
    deterministicFingerprint: o6kAgent24Fingerprint('imp_self', { v: 1 }),
  };
  const plan = buildAgent24ArchiveCompactionPlan({
    matchId: 'self',
    currentTurn: 20,
    historyRetention: retention,
    importValidation: importOk,
    replayEventCount: 40,
  });
  return [
    {
      name: 'eligible_bands_below_cutoff',
      passed: plan.eligibleBandCount >= 1 && plan.compactionSafe,
    },
    {
      name: 'deterministic_fingerprint',
      passed:
        plan.deterministicFingerprint ===
        buildAgent24ArchiveCompactionPlan({
          matchId: 'self',
          currentTurn: 20,
          historyRetention: retention,
          importValidation: importOk,
          replayEventCount: 40,
        }).deterministicFingerprint,
    },
  ];
}


// --- source: replay-transfer-gate.ts ---

export type Agent24ReplayTransferBlockerKind =
  | 'import_invalid'
  | 'manifest_incomplete'
  | 'retention_below_threshold'
  | 'no_prune_anchor';

export interface Agent24ReplayTransferBlocker {
  kind: Agent24ReplayTransferBlockerKind;
  detail: string;
  fingerprint: string;
}

export interface Agent24ReplayTransferGateReport {
  reportId: string;
  matchId: string;
  transferAllowed: boolean;
  blockerCount: number;
  blockers: Agent24ReplayTransferBlocker[];
  transferScore: number;
  deterministicFingerprint: string;
}

export interface Agent24ReplayTransferGateInput {
  matchId: string;
  manifest: Agent24ExportManifest;
  importValidation: Agent24ImportValidationReport;
  historyRetention: Agent24HistoryRetentionReport;
  minRetentionScore?: number;
}

export function buildAgent24ReplayTransferGateReport(
  input: Agent24ReplayTransferGateInput,
): Agent24ReplayTransferGateReport {
  const minRetention = input.minRetentionScore ?? 55;
  const blockers: Agent24ReplayTransferBlocker[] = [];

  if (!input.importValidation.valid) {
    blockers.push({
      kind: 'import_invalid',
      detail: `Import validation failed (${input.importValidation.issueCount} issues)`,
      fingerprint: o6kAgent24Fingerprint('transfer_import', { issues: input.importValidation.issueCount }),
    });
  }
  if (!input.manifest.complete) {
    blockers.push({
      kind: 'manifest_incomplete',
      detail: 'Export manifest incomplete for transfer',
      fingerprint: o6kAgent24Fingerprint('transfer_manifest', { complete: false }),
    });
  }
  if (input.historyRetention.retentionScore < minRetention) {
    blockers.push({
      kind: 'retention_below_threshold',
      detail: `Retention score ${input.historyRetention.retentionScore} below ${minRetention}`,
      fingerprint: o6kAgent24Fingerprint('transfer_retention', {
        score: input.historyRetention.retentionScore,
        min: minRetention,
      }),
    });
  }
  if (input.historyRetention.pruneSafeCutoffTurn <= 0) {
    blockers.push({
      kind: 'no_prune_anchor',
      detail: 'No prune-safe cutoff turn established',
      fingerprint: o6kAgent24Fingerprint('transfer_prune_anchor', { cutoff: 0 }),
    });
  }

  blockers.sort((a, b) => a.kind.localeCompare(b.kind));
  let transferScore = 100;
  transferScore -= blockers.length * 24;
  transferScore = Math.max(0, Math.min(100, transferScore));
  const transferAllowed = blockers.length === 0;

  return {
    reportId: o6kAgent24Fingerprint('replay_transfer_gate', { matchId: input.matchId, transferAllowed }),
    matchId: input.matchId,
    transferAllowed,
    blockerCount: blockers.length,
    blockers,
    transferScore,
    deterministicFingerprint: o6kAgent24Fingerprint('replay_transfer_gate_body', {
      blockers: blockers.map(b => b.fingerprint),
      transferAllowed,
      transferScore,
    }),
  };
}

export function runAgent24ReplayTransferGateSelfTests(): Array<{ name: string; passed: boolean }> {
  const manifest = {
    manifestId: 'm',
    matchId: 'self',
    sectionCount: 4,
    requiredSectionCount: 3,
    sections: [{ kind: 'composite_bundle' as const, label: 'c', fingerprint: 'fp', required: true }],
    compositeBundleFingerprint: 'live',
    complete: true,
    deterministicFingerprint: o6kAgent24Fingerprint('man_self', { v: 1 }),
  };
  const importOk = {
    reportId: 'i',
    matchId: 'self',
    valid: true,
    issueCount: 0,
    issues: [],
    validationScore: 100,
    deterministicFingerprint: o6kAgent24Fingerprint('imp_self', { v: 1 }),
  };
  const retention = {
    reportId: 'r',
    matchId: 'self',
    currentTurn: 12,
    retentionWindowTurns: 12,
    pruneSafeCutoffTurn: 8,
    bands: [],
    bandCount: 0,
    retentionScore: 75,
    deterministicFingerprint: o6kAgent24Fingerprint('ret_self', { v: 1 }),
  };
  const gate = buildAgent24ReplayTransferGateReport({
    matchId: 'self',
    manifest,
    importValidation: importOk,
    historyRetention: retention,
  });
  return [
    { name: 'allows_clean_bundle', passed: gate.transferAllowed && gate.blockerCount === 0 },
    {
      name: 'deterministic_fingerprint',
      passed:
        gate.deterministicFingerprint ===
        buildAgent24ReplayTransferGateReport({
          matchId: 'self',
          manifest,
          importValidation: importOk,
          historyRetention: retention,
        }).deterministicFingerprint,
    },
  ];
}


// --- source: snapshot-seal.ts ---

export interface Agent24SnapshotSealLink {
  label: string;
  fingerprint: string;
}

export interface Agent24SnapshotSeal {
  sealId: string;
  matchId: string;
  turn: number;
  sealed: boolean;
  linkCount: number;
  links: Agent24SnapshotSealLink[];
  compositeBundleFingerprint: string;
  sealFingerprint: string;
  deterministicFingerprint: string;
}

export interface Agent24SnapshotSealInput {
  matchId: string;
  turn: number;
  compositeBundleFingerprint: string;
  manifest: Agent24ExportManifest;
  importValidation: Agent24ImportValidationReport;
  transferGate: Agent24ReplayTransferGateReport;
  archiveCompaction: Agent24ArchiveCompactionPlan;
}

export function buildAgent24SnapshotSeal(input: Agent24SnapshotSealInput): Agent24SnapshotSeal {
  const links: Agent24SnapshotSealLink[] = [
    { label: 'composite_bundle', fingerprint: input.compositeBundleFingerprint },
    { label: 'export_manifest', fingerprint: input.manifest.deterministicFingerprint },
    { label: 'import_validation', fingerprint: input.importValidation.deterministicFingerprint },
    { label: 'transfer_gate', fingerprint: input.transferGate.deterministicFingerprint },
    { label: 'archive_compaction', fingerprint: input.archiveCompaction.deterministicFingerprint },
  ];
  links.sort((a, b) => a.label.localeCompare(b.label));

  const sealed =
    input.importValidation.valid &&
    input.manifest.complete &&
    input.transferGate.transferAllowed &&
    input.archiveCompaction.compactionSafe;

  const sealFingerprint = o6kAgent24Fingerprint('snapshot_seal_chain', {
    links: links.map(l => ({ label: l.label, fp: l.fingerprint })),
    sealed,
  });

  return {
    sealId: o6kAgent24Fingerprint('snapshot_seal', { matchId: input.matchId, turn: input.turn }),
    matchId: input.matchId,
    turn: input.turn,
    sealed,
    linkCount: links.length,
    links,
    compositeBundleFingerprint: input.compositeBundleFingerprint,
    sealFingerprint,
    deterministicFingerprint: o6kAgent24Fingerprint('snapshot_seal_body', {
      sealFingerprint,
      sealed,
      linkCount: links.length,
    }),
  };
}

